import crypto3 from "crypto";
import { Router as Router3 } from "express";
import log6 from "electron-log";

// ../shared/nextExamApiSecret.js
var NEXT_EXAM_API_SECRET = "NEXT-EXAM";
var NEXT_EXAM_API_TS_HEADER = "x-next-exam-app-ts";
var NEXT_EXAM_API_MAC_HEADER = "x-next-exam-app-mac";
var NEXT_EXAM_API_TS_WINDOW_MS = 3e5;
var enc = new TextEncoder();
async function computeAppMac(message) {
  const key = await crypto.subtle.importKey("raw", enc.encode(NEXT_EXAM_API_SECRET), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const sig = await crypto.subtle.sign("HMAC", key, enc.encode(String(message)));
  return btoa(String.fromCharCode(...new Uint8Array(sig)));
}

