    ipcMain2.handle("duplicateExam", async (_event, payload = {}) => {
      const sourceName = typeof payload.sourceName === "string" ? payload.sourceName.trim().toLowerCase() : "";
      const targetName = typeof payload.targetName === "string" ? payload.targetName.trim().toLowerCase() : "";
      if (!/^[a-z0-9_-]{1,20}$/.test(sourceName) || !/^[a-z0-9_-]{1,20}$/.test(targetName)) {
        return { status: "error", message: "invalid exam name" };
      }
      const sourceFile = resolvePathUnderRoot(config2.workdirectory, [sourceName, "serverstatus.json"]);
      const targetDir = resolvePathUnderRoot(config2.workdirectory, [targetName]);
      const targetFile = resolvePathUnderRoot(config2.workdirectory, [targetName, "serverstatus.json"]);
      if (!sourceFile || !targetDir || !targetFile || fs11.existsSync(targetDir)) {
        return { status: "error", message: "exam already exists or source is invalid" };
      }
      try {
        const duplicate = JSON.parse(await fs11.promises.readFile(sourceFile, "utf-8"));
        duplicate.examName = targetName;
        duplicate.id = crypto7.randomUUID();
        await fs11.promises.mkdir(targetDir);
        await fs11.promises.writeFile(targetFile, JSON.stringify(duplicate, null, 2));
        return { status: "success" };
      } catch (err) {
        log14.error(`ipchandler @ duplicateExam: ${err}`);
        return { status: "error", message: "could not duplicate exam" };
      }
    });
