    ipcMain2.handle("exportActivesheetsZip", async (_event, payload = {}) => {
      const { servername, servertoken, filename, pdfBase64, customFields, blacklist, formFieldsOnly, formData } = payload;
      const mcServer = this.config.examServerList[servername];
      if (!mcServer || servertoken !== mcServer.serverinfo?.servertoken) {
        return { status: "error", message: t4("data.tokennotvalid") };
      }
      const pdfName = path11.basename(String(filename || "activesheet.pdf"));
      const htmName = activesheetsTemplateName(pdfName);
      const result = await dialog2.showSaveDialog(this.WindowHandler.mainwindow, {
        defaultPath: htmName.replace(/_korrekturvorlage\.htm$/, "_activesheet.zip"),
        filters: [{ name: "ZIP", extensions: ["zip"] }]
      });
      if (result.canceled || !result.filePath) return { status: "cancelled" };
      try {
        const archive = archiver2("zip", { zlib: { level: 9 } });
        const stream = fs11.createWriteStream(result.filePath);
        const done = new Promise((resolve, reject) => {
          stream.on("close", resolve);
          archive.on("error", reject);
        });
        archive.pipe(stream);
        const b64 = String(pdfBase64 || "");
        archive.append(Buffer.from(b64.slice(b64.indexOf(",") + 1), "base64"), { name: pdfName });
        archive.append(JSON.stringify({ version: 1, filename: pdfName, customFields: customFields || [], blacklist: blacklist || [], formFieldsOnly: !!formFieldsOnly }, null, 2), { name: "activesheet.json" });
        const templatePath = resolvePathUnderRoot(this.config.workdirectory, [mcServer.serverinfo.servername, "activesheets", htmName]);
        if (templatePath && formData && typeof formData === "object") {
          await fs11.promises.mkdir(path11.dirname(templatePath), { recursive: true });
          await fs11.promises.writeFile(templatePath, JSON.stringify(formData, null, 2), "utf8");
        }
        if (templatePath && fs11.existsSync(templatePath)) archive.file(templatePath, { name: htmName });
        archive.finalize();
        await done;
        log14.info(`ipchandler @ exportActivesheetsZip: wrote ${result.filePath}`);
        return { status: "success", filepath: result.filePath };
      } catch (err) {
        log14.error("ipchandler @ exportActivesheetsZip:", err);
        return { status: "error", message: t4("data.fileerror") };
      }
    });
    ipcMain2.handle("importActivesheetsZip", async (_event, payload = {}) => {
      const { servername, servertoken, zipBase64 } = payload;
      const mcServer = this.config.examServerList[servername];
      if (!mcServer || servertoken !== mcServer.serverinfo?.servertoken) {
        return { status: "error", message: t4("data.tokennotvalid") };
      }
      const tmpDir = await fs11.promises.mkdtemp(path11.join(tmpdir(), "nxe-activesheet-"));
      try {
        const zipPath = path11.join(tmpDir, "import.zip");
        const outDir = path11.join(tmpDir, "out");
        await fs11.promises.writeFile(zipPath, Buffer.from(String(zipBase64 || ""), "base64"));
        await extractZip(zipPath, { dir: outDir });
        const names = await fs11.promises.readdir(outDir);
        const pdfName = names.find((n) => n.toLowerCase().endsWith(".pdf"));
        if (!pdfName) return { status: "error", message: t4("data.fileerror") };
        const meta = names.includes("activesheet.json") ? JSON.parse(await fs11.promises.readFile(path11.join(outDir, "activesheet.json"), "utf8")) : {};
        const templateSrc = names.find((n) => n.toLowerCase().endsWith("_korrekturvorlage.htm"));
        if (templateSrc) {
          const templateTarget = resolvePathUnderRoot(this.config.workdirectory, [mcServer.serverinfo.servername, "activesheets", activesheetsTemplateName(pdfName)]);
          if (templateTarget) {
            await fs11.promises.mkdir(path11.dirname(templateTarget), { recursive: true });
            await fs11.promises.copyFile(path11.join(outDir, templateSrc), templateTarget);
          }
        }
        const pdfBuffer = await fs11.promises.readFile(path11.join(outDir, pdfName));
        log14.info(`ipchandler @ importActivesheetsZip: imported ${pdfName} template=${!!templateSrc}`);
        return {
          status: "success",
          filename: pdfName,
          pdfBase64: `data:application/pdf;base64,${pdfBuffer.toString("base64")}`,
          customFields: Array.isArray(meta.customFields) ? meta.customFields : [],
          blacklist: Array.isArray(meta.blacklist) ? meta.blacklist : [],
          formFieldsOnly: !!meta.formFieldsOnly
        };
      } catch (err) {
        log14.error("ipchandler @ importActivesheetsZip:", err);
        return { status: "error", message: t4("data.fileerror") };
      } finally {
        await fs11.promises.rm(tmpDir, { recursive: true, force: true }).catch(() => {
        });
      }
    });
