    ipcMain2.handle("getSubmissions", async (event, servername, currentserverstatus) => {
      const mcServer = this.config.examServerList[servername];
      const serverstatus = JSON.parse(currentserverstatus);
      if (!mcServer) {
        return { sender: "server", message: "notfound", status: "error", submissions: [] };
      }
      let submissions = [];
      let dir = join4(config2.workdirectory, mcServer.serverinfo.servername);
      if (fs11.existsSync(dir)) {
        const folders = fs11.readdirSync(dir, { withFileTypes: true }).filter((dirent) => dirent.isDirectory()).map((dirent) => dirent.name);
        for (const studentName of folders) {
          if (NON_STUDENT_ROOT_DIRS.has(studentName.toLowerCase())) {
            continue;
          }
          let sections = {};
          let submissionDir = join4(dir, studentName, "ABGABE");
          for (let section = 1; section <= 4; section++) {
            let sectionDir = join4(submissionDir, String(section));
            sections[section] = {
              path: null,
              filename: "",
              date: false,
              sectionname: ""
            };
            if (fs11.existsSync(sectionDir)) {
              let sectionFiles = fs11.readdirSync(sectionDir, { withFileTypes: true }).filter((dirent) => dirent.isFile()).map((dirent) => dirent.name).filter((file) => /\.pdf$/i.test(file));
              if (sectionFiles.length > 0) {
                let latestSubmission = sectionFiles.map((file) => {
                  let filePath = join4(sectionDir, file);
                  return { file, mtime: fs11.statSync(filePath).mtime };
                }).sort((a, b) => b.mtime - a.mtime)[0];
                sections[section] = {
                  path: join4(sectionDir, latestSubmission.file),
                  filename: latestSubmission.file,
                  date: latestSubmission.mtime,
                  sectionname: serverstatus.examSections[section].sectionname
                };
              }
            }
          }
          submissions.push({
            studentName,
            sections
          });
        }
      }
      return submissions;
    });
